svg.script:
(function () {
  "use strict";
  var SVG_NS = "http://www.w3.org/2000/svg";
  var stateEl = document.getElementById("alpha-state");
  var logEl = document.getElementById("log");
  var dynEl = document.getElementById("dynamic-layer");
  var inputEl = document.getElementById("expr");
  var outEl = document.getElementById("result");

  function getState() { return JSON.parse(stateEl.textContent); }
  function setState(s) { stateEl.textContent = JSON.stringify(s); }

  function log(msg) {
    var t = document.createElementNS(SVG_NS, "tspan");
    t.setAttribute("x", "20");
    t.setAttribute("dy", "1.2em");
    t.textContent = msg;
    logEl.appendChild(t);
    if (logEl.childNodes.length > 8) { logEl.removeChild(logEl.firstChild); }
  }

  // --- Alpha-20 tokenizer / parser (subset used by the demo) ---
  function tokenize(src) {
    var re = /\s*(\d+\.\d+|\d+|[A-Za-z_][A-Za-z0-9_]*|"[^"]*"|[(),])/g;
    var toks = [], m;
    while ((m = re.exec(src)) !== null) { toks.push(m[1]); }
    return toks;
  }
  function parse(toks) {
    var i = 0;
    function peek() { return toks[i]; }
    function eat(v) { if (toks[i] !== v) { throw new Error("expected " + v + " got " + toks[i]); } i++; }
    function expr() {
      if (peek() === "IF") {
        eat("IF"); var c = expr(); eat("THEN"); var t = expr();
        var e = null; if (peek() === "ELSE") { eat("ELSE"); e = expr(); }
        return {op:"IF", c:c, t:t, e:e};
      }
      if (peek() === "NOT") { eat("NOT"); return {op:"NOT", v:expr()}; }
      var left = atom();
      while (peek() === "AND" || peek() === "OR") {
        var op = toks[i++]; var right = atom(); left = {op:op, l:left, r:right};
      }
      return left;
    }
    function atom() {
      var t = peek();
      if (/^\d/.test(t)) { i++; return {op:"NUM", v:parseFloat(t)}; }
      if (t === "(") { eat("("); var e = expr(); eat(")"); return e; }
      if (/^[A-Za-z_]/.test(t)) {
        var name = toks[i++];
        if (peek() === "(") {
          eat("("); var args = [];
          if (peek() !== ")") { args.push(expr()); while (peek() === ",") { eat(","); args.push(expr()); } }
          eat(")"); return {op:"CALL", name:name, args:args};
        }
        return {op:"ID", name:name};
      }
      throw new Error("unexpected " + t);
    }
    var ast = expr();
    if (i !== toks.length) { throw new Error("trailing tokens"); }
    return ast;
  }
  function evalNode(n) {
    if (n.op === "NUM") { return n.v; }
    if (n.op === "ID") { return n.name; }
    if (n.op === "AND") { return evalNode(n.l) && evalNode(n.r); }
    if (n.op === "OR") { return evalNode(n.l) || evalNode(n.r); }
    if (n.op === "NOT") { return !evalNode(n.v); }
    if (n.op === "IF") { return evalNode(n.c) ? evalNode(n.t) : (n.e ? evalNode(n.e) : null); }
    if (n.op === "CALL") {
      var a = n.args.map(evalNode);
      if (n.name === "SAME") { return a[0] === a[1]; }
      if (n.name === "BIG") { return a[0] > a[1]; }
      if (n.name === "MOVE") { return (a[2] - a[1]) > 0; }
      if (n.name === "TRUE") { return true; }
      if (n.name === "EXIST") { return true; }
      if (n.name === "LIVE") { return true; }
      return null;
    }
    throw new Error("unknown node " + n.op);
  }

  // --- SHA-256 fallback (works in file:// where crypto.subtle is blocked) ---
  function sha256Fallback(ascii) {
    function rightRotate(v, a) { return (v >>> a) | (v << (32 - a)); }
    var mathPow = Math.pow, maxWord = mathPow(2, 32), result = "", words = [], asciiBitLength = ascii.length * 8;
    var hash = sha256Fallback.h = sha256Fallback.h || [];
    var k = sha256Fallback.k = sha256Fallback.k || [];
    var primeCounter = k.length;
    var isComposite = {};
    for (var candidate = 2; primeCounter < 64; candidate++) {
      if (!isComposite[candidate]) {
        for (var i = 0; i < 313; i += candidate) { isComposite[i] = candidate; }
        hash[primeCounter] = (mathPow(candidate, .5) * maxWord) | 0;
        k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
      }
    }
    ascii += "\x80";
    while (ascii.length % 64 - 56) { ascii += "\x00"; }
    for (i = 0; i < ascii.length; i++) {
      var j = ascii.charCodeAt(i);
      if (j >> 8) { return; }
      words[i >> 2] |= j << ((3 - i) % 4) * 8;
    }
    words[words.length] = ((asciiBitLength / maxWord) | 0);
    words[words.length] = asciiBitLength;
    for (j = 0; j < words.length;) {
      var w = words.slice(j, j += 16);
      var oldHash = hash.slice(0, 8);
      for (i = 0; i < 64; i++) {
        var w15 = w[i - 15], w2 = w[i - 2];
        var a = hash[0], e = hash[4];
        var temp1 = hash[7] + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) + ((e & hash[5]) ^ ((~e) & hash[6])) + k[i]
          + (w[i] = (i < 16) ? w[i] : (w[i - 16] + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) | 0);
        var temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
        hash = [(temp1 + temp2) | 0].concat(hash);
        hash[4] = (hash[4] + temp1) | 0;
      }
      for (i = 0; i < 8; i++) { hash[i] = (hash[i] + oldHash[i]) | 0; }
    }
    for (i = 0; i < 8; i++) {
      for (j = 3; j + 1; j--) {
        var b = (hash[i] >> (j * 8)) & 255;
        result += ((b < 16) ? 0 : "") + b.toString(16);
      }
    }
    return result;
  }

  function sha256(text) {
    if (window.crypto && window.crypto.subtle) {
      var buf = new TextEncoder().encode(text);
      return window.crypto.subtle.digest("SHA-256", buf).then(function (h) {
        return Array.from(new Uint8Array(h)).map(function (b) { return b.toString(16).padStart(2, "0"); }).join("");
      });
    }
    return Promise.resolve(sha256Fallback(text));
  }

  // --- rendering ---
  function renderGlyphs(prims) {
    while (dynEl.firstChild) { dynEl.removeChild(dynEl.firstChild); }
    prims.forEach(function (p, idx) {
      var g = document.createElementNS(SVG_NS, "g");
      g.setAttribute("transform", "translate(" + (560 + (idx % 2) * 80) + "," + (40 + Math.floor(idx / 2) * 80) + ")");
      var c = document.createElementNS(SVG_NS, "circle");
      c.setAttribute("cx", "30"); c.setAttribute("cy", "30"); c.setAttribute("r", "20");
      c.setAttribute("fill", "#1f77b4"); c.setAttribute("opacity", "0.85");
      var t = document.createElementNS(SVG_NS, "text");
      t.setAttribute("x", "30"); t.setAttribute("y", "70");
      t.setAttribute("font-family", "monospace"); t.setAttribute("font-size", "10");
      t.setAttribute("text-anchor", "middle"); t.setAttribute("fill", "#222");
      t.textContent = p;
      g.appendChild(c); g.appendChild(t); dynEl.appendChild(g);
    });
  }

  function collectPrims(n, acc) {
    acc = acc || [];
    if (!n || typeof n !== "object") { return acc; }
    if (n.op === "CALL") { acc.push(n.name); n.args.forEach(function (a) { collectPrims(a, acc); }); }
    if (n.op === "AND" || n.op === "OR") { collectPrims(n.l, acc); collectPrims(n.r, acc); }
    if (n.op === "NOT") { collectPrims(n.v, acc); }
    if (n.op === "IF") { collectPrims(n.c, acc); collectPrims(n.t, acc); if (n.e) { collectPrims(n.e, acc); } }
    return acc;
  }

  // --- actions ---
  function onEvaluate() {
    try {
      var src = (inputEl && inputEl.value || "MOVE(particle, 0, 10) AND SAME(10, 10) AND BIG(10, 0)").trim();
      var ast = parse(tokenize(src));
      var val = evalNode(ast);
      var prims = collectPrims(ast);
      renderGlyphs(prims);
      var s = getState();
      s.history.push({ expr: src, value: val, prims: prims, at: new Date().toISOString() });
      s.sealed = false; s.last_hash = null;
      setState(s);
      outEl.textContent = "RESULT: " + String(val);
      log("evaluated: " + src + " -> " + String(val));
    } catch (e) {
      outEl.textContent = "ERROR: " + e.message;
      log("error: " + e.message);
    }
  }

  function onSeal() {
    var s = getState();
    var canon = JSON.stringify(s);
    sha256(canon).then(function (h) {
      s.sealed = true; s.last_hash = h;
      setState(s);
      outEl.textContent = "SEALED: " + h.slice(0, 16) + "...";
      log("sealed: " + h.slice(0, 16) + "...");
    }).catch(function (e) {
      outEl.textContent = "SEAL ERROR: " + e.message;
    });
  }

  function onReset() {
    setState({ version: "0.1.0", sealed: false, last_hash: null, history: [], knowledge: getState().knowledge });
    renderGlyphs([]);
    outEl.textContent = "RESET";
    log("state reset");
  }

  // --- wiring ---
  var bEval = document.getElementById("btn-eval");
  var bSeal = document.getElementById("btn-seal");
  var bReset = document.getElementById("btn-reset");
  if (bEval) { bEval.addEventListener("click", onEvaluate); }
  if (bSeal) { bSeal.addEventListener("click", onSeal); }
  if (bReset) { bReset.addEventListener("click", onReset); }
  ["keydown"].forEach(function (evt) {
    [bEval, bSeal, bReset].forEach(function (b) {
      if (b) { b.addEventListener(evt, function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); b.dispatchEvent(new Event("click")); } }); }
    });
  });
})();
